2	import { describe, test } from "node:test";
3	import { countryOf, isValidLocode, normaliseLocode } from "@harbor/dispatch/ports/locode";
4	import { classesForPort, portByCode, portsInCountry, vesselClass } from "@harbor/dispatch/ports/registry";
5	
6	describe("locode", () => {
7	  test("case is normalised", () => {
8	    assert.equal(normaliseLocode(" nlrtm "), "NLRTM");
9	    assert.equal(isValidLocode("sgsin"), true);
10	  });
11	
12	  test("malformed codes are invalid", () => {
13	    assert.equal(isValidLocode("NL"), false);
14	    assert.throws(() => countryOf("12345"), RangeError);
15	  });
16	
17	  test("country", () => {
18	    assert.equal(countryOf("DEHAM"), "DE");
19	  });
20	});
21	
22	describe("registry", () => {
23	  test("ports by code", () => {
24	    assert.equal(portByCode("nlrtm")?.name, "Rotterdam");
25	    assert.equal(portByCode("XXZZZ"), undefined);
26	  });
27	
28	  test("ports by country", () => {
29	    assert.deepEqual(portsInCountry("us").map((p) => p.code), ["USLAX", "USNYC"]);
30	  });
31	
32	  test("vessel classes", () => {
33	    assert.equal(vesselClass("panamax")?.teu, 5000);
34	    const hamburg = portByCode("DEHAM");
35	    assert.ok(hamburg);
36	    assert.equal(classesForPort(hamburg).some((v) => v.name === "ULCV"), false);
